/* Hallmark · pre-emit critique: P5 H4 E4 S5 R5 V4 · one day list drives one real map */
(() => {
  const registry=window.XIANGYE_PLACES;
  let map=null,routeLine=null,routeAbort=null,routeSerial=0,lastRouteAt=0;
  const html=value=>escapeHtml(String(value??''));
  const dayIndex=t=>Math.max(0,Math.min(t.days.length-1,Number(state.mapDay)||0));
  const current=()=>{const t=trip(),d=registry.destination(t),i=t?dayIndex(t):0;return {t,d,i,day:t?.days?.[i]}};
  const candidates=d=>registry.forDestination(d);
  const stops=(day,d)=>(day?.places||[]).map(key=>registry.byKey(key,d)||{name:key.split('|')[0],city:key.split('|')[1]||'',id:key,kind:'地点',summary:'地点资料待补充。',sources:[]});
  const saved=(p,day)=>day?.places?.includes(`${p.name}|${p.city||''}`);
  const card=(p,day)=>{const manual=p.kind==='自选坐标';return `<div class="trip-pin-card"><strong>${html(p.name)}</strong><small>${html(p.city||'')} · ${html(p.kind||'地点')} · ${html(p.positionStatus||'坐标待核对')}</small><p>${html(p.summary||'资料待核对。')}</p>${p.guide?`<p class="trip-guide-note">讲解：${html(p.guide.lead)}</p>`:''}<div class="trip-pin-sources">${manual?'<span>此点由你选定，不附会景点讲解或营业时间。</span>':(p.sources||[]).map(s=>`<a href="${html(s.url)}" target="_blank" rel="noopener noreferrer">${html(s.label)} ↗</a>`).join('')||'<span>讲解来源待核对</span>'}</div>${manual?'':`<div class="trip-pin-opening"><a href="${html(p.openingUrl||`https://www.google.com/search?q=${encodeURIComponent(`${p.name} ${p.city||''} 开放时间 官方`)}`)}" target="_blank" rel="noopener noreferrer">${p.openingUrl?'官方开放信息 ↗':'搜索最新开放信息 ↗'}</a><small>出发前请再核对，页面不显示未经更新的营业时间。</small></div>`}<div class="trip-pin-actions"><button type="button" data-action="trip-map-toggle" data-place-id="${html(p.id)}">${saved(p,day)?'从这一天移出':'加入这一天'}</button>${p.guide?`<button type="button" data-action="trip-map-guide" data-place-id="${html(p.id)}">读完整讲解</button>`:''}</div></div>`};
  function panel(t,d,i,day){const all=candidates(d),list=stops(day,d),known=list.filter(registry.coordinates),unknown=list.length-known.length;return `<section class="trip-map-workspace" id="trip-map-workspace"><div class="section-heading"><h2 class="section-title">把这一天放在地图上</h2></div><p class="section-note">先在下面写好想去的地方；地图会按当天顺序显示编号。只标出有坐标的地点。</p><div class="route-day-tabs-x" role="group" aria-label="地图日期">${t.days.map((x,j)=>`<button type="button" class="${j===i?'selected':''}" data-action="trip-map-day" data-day="${j}" aria-pressed="${j===i}">第${j+1}天</button>`).join('')}</div><div class="trip-map-canvas" id="trip-map-canvas" role="application" aria-label="第${i+1}天多地点地图"></div><div id="trip-map-status" class="trip-map-status" role="status">${known.length?`地图应显示 ${known.length} 个编号地点${unknown?`；${unknown} 个地点坐标待核对`:''}`:'先添加有坐标的地点，地图才会出现标记。'}</div><form id="trip-map-add" class="trip-map-add"><label class="field"><span>这一天想去哪里</span><input name="placeName" list="trip-map-places" placeholder="输入或选择博物馆、景点" autocomplete="off" required></label><datalist id="trip-map-places">${all.map(p=>`<option value="${html(p.name)}">${html(p.city||'')} · ${html(p.kind)}</option>`).join('')}</datalist><button type="submit" class="secondary">加入这一天</button></form><ol class="trip-stop-list">${list.map((p,j)=>`<li><span class="trip-stop-number">${j+1}</span><span class="trip-stop-text"><strong>${html(p.name)}</strong><small>${html(p.city||'')} · ${registry.coordinates(p)?'地图可见':'坐标待核对'}</small></span><div class="trip-stop-tools"><button type="button" data-action="trip-map-focus" data-place-id="${html(p.id)}" ${registry.coordinates(p)?'':'disabled'}>查看</button><button type="button" data-action="trip-map-move" data-index="${j}" data-shift="-1" ${j===0?'disabled':''} aria-label="${html(p.name)}上移">↑</button><button type="button" data-action="trip-map-move" data-index="${j}" data-shift="1" ${j===list.length-1?'disabled':''} aria-label="${html(p.name)}下移">↓</button><button type="button" data-action="trip-map-remove" data-index="${j}" aria-label="移除${html(p.name)}">移出</button></div></li>`).join('')||'<li class="trip-stop-empty">还没有站点。可从上方输入地点，或从景点页加入。</li>'}</ol><div id="trip-place-detail">${state.tripMapPlaceId?card(registry.byId(state.tripMapPlaceId,d)||list.find(p=>p.id===state.tripMapPlaceId)||all[0],day):''}</div><div class="trip-route-controls"><strong>路线方式</strong><div class="trip-route-modes">${[['foot','步行'],['car','驾车'],['intercity','跨城']].map(([mode,label])=>`<button type="button" data-action="trip-map-mode" data-mode="${mode}" class="${(state.tripRouteMode||'foot')===mode?'selected':''}" aria-pressed="${(state.tripRouteMode||'foot')===mode}">${label}</button>`).join('')}</div><button type="button" class="primary full" data-action="trip-map-route" ${known.length<2?'disabled':''}>计算这一天的真实道路</button><p id="trip-route-result" role="status">${known.length<2?'至少需要两个有坐标的站点。':'还没有计算路线；不显示虚构距离或时间。'}</p></div></section>`}
  const before=renderTrip;
  let lastContext='',lastTripId='';
  renderTrip=function(){const base=before();let {t,d,i,day}=current();if(!t||!d)return base;if(t.id!==lastTripId){state.mapDay=0;lastTripId=t.id;({t,d,i,day}=current())}const context=`${t.id}:${i}`;if(context!==lastContext){state.tripMapPlaceId=null;lastContext=context}const section=panel(t,d,i,day);return base.replace(/<section class="route-section-x">[\s\S]*?<\/section>/,section)};
  function initMap(){const host=document.getElementById('trip-map-canvas');if(!host)return;map?.remove();map=null;routeLine=null;if(!window.L){document.getElementById('trip-map-status').textContent='地图组件暂时无法加载；站点清单仍可编辑。';return}const {d,day}=current(),visible=stops(day,d).filter(registry.coordinates);const center=visible[0]||d;map=L.map(host,{zoomControl:false,scrollWheelZoom:false}).setView([Number(center.lat)||0,Number(center.lon)||0],visible.length?11:6);L.tileLayer('https://{s}.tile.openstreetmap.fr/osmfr/{z}/{x}/{y}.png',{subdomains:'abc',maxZoom:19,attribution:'© OpenStreetMap contributors · OpenStreetMap France'}).addTo(map);L.control.zoom({position:'bottomright'}).addTo(map);map.on('click',event=>document.dispatchEvent(new CustomEvent('xiangye:map-coordinate',{detail:{lat:event.latlng.lat,lon:event.latlng.lng}})));const bounds=[];visible.forEach((p,j)=>{const marker=L.marker([Number(p.lat),Number(p.lon)],{icon:L.divIcon({html:`<span class="trip-number-pin">${j+1}</span>`,className:'trip-number-icon',iconSize:[36,40],iconAnchor:[18,40]}),title:p.name}).addTo(map);marker.on('click',()=>focus(p.id));bounds.push([Number(p.lat),Number(p.lon)])});if(bounds.length>1)map.fitBounds(bounds,{padding:[35,35],maxZoom:13});if(bounds.length===1)map.setView(bounds[0],13)}
  const beforeRender=render;
  render=function(){beforeRender();if(state.view==='trip')requestAnimationFrame(initMap)};
  function refresh(){routeSerial++;routeAbort?.abort();routeAbort=null;state.tripRouteResult=null;render()}
  function focus(id){const {d,day}=current(),p=registry.byId(id,d)||stops(day,d).find(x=>x.id===id);if(!p)return;state.tripMapPlaceId=id;document.getElementById('trip-place-detail').innerHTML=card(p,day);document.getElementById('trip-place-detail').scrollIntoView({behavior:'smooth',block:'nearest'});if(map&&registry.coordinates(p))map.flyTo([Number(p.lat),Number(p.lon)],Math.max(map.getZoom(),14),{animate:false})}
  document.addEventListener('submit',event=>{if(event.target.id!=='trip-map-add')return;event.preventDefault();const {t,d,day}=current(),value=String(new FormData(event.target).get('placeName')||'').trim(),matches=candidates(d).filter(p=>p.name===value);if(!t||!matches.length){notify('还没有这个地点的可靠记录。请先在搜索页查找，再加入行程。');return}if(matches.length>1){notify('有重名地点，请先到景点页确认。');return}const p=matches[0],key=`${p.name}|${p.city||''}`;if(day.places.includes(key)){notify('这一天已经有这个地点。');return}day.places.push(key);saveTrip(t);state.tripMapPlaceId=p.id;refresh();notify('地点已加入当天清单与地图。')});
  document.addEventListener('click',event=>{const button=event.target.closest?.('[data-action^="trip-map-"]');if(!button)return;const action=button.dataset.action,{t,d,day}=current();if(!t)return;
    if(action==='trip-map-day'){state.mapDay=Number(button.dataset.day);state.tripMapPlaceId=null;refresh();requestAnimationFrame(()=>document.getElementById('trip-map-workspace')?.scrollIntoView({behavior:'smooth',block:'start'}));return}
    if(action==='trip-map-mode'){state.tripRouteMode=button.dataset.mode;refresh();return}
    if(action==='trip-map-focus'){focus(button.dataset.placeId);return}
    if(action==='trip-map-guide'){const p=registry.byId(button.dataset.placeId,d);if(p?.guide)location.href=`egypt-atlas.html?trip=${encodeURIComponent(t.id)}&place=${encodeURIComponent(p.guide.id)}&day=${dayIndex(t)}`;return}
    if(action==='trip-map-toggle'){const p=registry.byId(button.dataset.placeId,d);if(!p)return;const key=`${p.name}|${p.city||''}`;day.places=saved(p,day)?day.places.filter(x=>x!==key):[...day.places,key];saveTrip(t);refresh();return}
    if(action==='trip-map-remove'){const index=Number(button.dataset.index);if(index>=0&&index<day.places.length){day.places.splice(index,1);saveTrip(t);refresh()}return}
    if(action==='trip-map-move'){const index=Number(button.dataset.index),target=index+Number(button.dataset.shift);if(target<0||target>=day.places.length)return;[day.places[index],day.places[target]]=[day.places[target],day.places[index]];saveTrip(t);refresh();return}
    if(action==='trip-map-route')calculateRoute();
  });
  async function calculateRoute(){const {d,day}=current(),points=stops(day,d).filter(registry.coordinates),mode=state.tripRouteMode||'foot',output=document.getElementById('trip-route-result');routeLine?.remove();routeLine=null;if(points.length<2){output.textContent='至少需要两个有坐标的站点。';return}if(mode==='intercity'){output.innerHTML='跨城可能涉及飞机、火车或巴士，单一道路估算会误导。请按实际班次核对。 <a target="_blank" rel="noopener noreferrer" href="https://www.google.com/maps/dir/?api=1&origin='+encodeURIComponent(points[0].name+', '+points[0].city)+'&destination='+encodeURIComponent(points.at(-1).name+', '+points.at(-1).city)+'">在外部地图核对 ↗</a>';return}if(points.length>10){output.textContent='一次最多计算10站；请拆分当天路线。';return}const direct=points.slice(1).some((p,i)=>registry.distanceKm(points[i],p)>150);if(direct){output.textContent='相邻站点超过150公里，可能需要跨城交通。请切换“跨城”并核对班次。';return}if(Date.now()-lastRouteAt<1200){output.textContent='请稍等一秒再计算，避免频繁请求公共道路服务。';return}lastRouteAt=Date.now();const serial=++routeSerial;routeAbort?.abort();routeAbort=new AbortController();const controller=routeAbort;let timedOut=false;const timer=setTimeout(()=>{timedOut=true;controller.abort()},12000);output.textContent='正在向道路服务查询…';const path=points.map(p=>`${Number(p.lon)},${Number(p.lat)}`).join(';'),profile=mode==='car'?'routed-car':'routed-foot';try{const response=await fetch(`https://routing.openstreetmap.de/${profile}/route/v1/driving/${path}?overview=full&geometries=geojson&steps=false`,{signal:controller.signal});if(!response.ok)throw Error('route unavailable');const data=await response.json();if(serial!==routeSerial)return;const route=data.routes?.[0];if(data.code!=='Ok'||!route||!Array.isArray(route.geometry?.coordinates))throw Error('route unavailable');const km=(route.distance/1000).toFixed(1),minutes=Math.round(route.duration/60),hours=minutes>=60?`${Math.floor(minutes/60)}小时${minutes%60}分`:`${minutes}分钟`;output.textContent=`${mode==='car'?'驾车':'步行'}道路估算：约 ${km} 公里 · ${hours}。不含实时路况、排队或停留；路线由 FOSSGIS / OpenStreetMap 提供。`;routeLine=L.geoJSON(route.geometry,{style:{color:getComputedStyle(document.documentElement).getPropertyValue('--color-forest').trim()||getComputedStyle(document.documentElement).getPropertyValue('--color-ink').trim(),weight:5,opacity:.8}}).addTo(map);map.fitBounds(routeLine.getBounds(),{padding:[24,24]})}catch(error){if(error.name==='AbortError'&&!timedOut)return;output.textContent=timedOut?'道路服务响应超时。站点已保存，请稍后重试或用外部地图核对。':'道路服务没有返回可靠路线。站点仍已保存；请稍后重试或用外部地图核对。'}finally{clearTimeout(timer)}}
  render();
})();
